interface.definition:
a!localVariables(
  local!bus: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(returnCDT: true, isActive: true),
  local!oldBus: index(
    local!bus,
    wherecontains(
      {
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296"
      },
      index(local!bus, "regionId", {})
    )
  ),
  local!newBus: index(
    local!bus,
    wherecontains(406, index(local!bus, "regionId", {}))
  ),
  local!selectedRegion,
  local!selectedBU,
  local!rotationalAskPlan: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906867"(fiscalYear: ri!fiscalYear),
  local!totalRotationalPlanned: sum(
    index(local!rotationalAskPlan, "plan", 0)
  ),
  local!actualNominationsWithAsks: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6752972"(
    fiscalYear: ri!fiscalYear,
    posititionTypeId: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    subPositionTypeId: { 10, 18, 19, 6, 7, 20 },
    columns: { "askID", "buID", "statusId" }
  ).data,
  local!asksCount: length(local!actualNominationsWithAsks),
  local!completedAsksCount: length(
    wherecontains(
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350",
      tointeger(index(local!actualNominationsWithAsks, "statusId", {}))
    )
  ),
  local!inProgressAsks: local!asksCount - local!completedAsksCount,
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_sectionLayout_v1"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "FY " & ri!fiscalYear & " Rotationals",
                    color: "ACCENT",
                    size: "LARGE",
                    style: "STRONG"
                  ),
                  align: "CENTER"
                ),
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!totalRotationalPlanned,
                              color: "ACCENT",
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "ASK",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!asksCount,
                              color: if(
                                local!asksCount <> local!totalRotationalPlanned,
                                "NEGATIVE",
                                "POSITIVE"
                              ),
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Confirmed/In Process",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    )
                  }
                )
              }
            ),
            width: "MEDIUM_PLUS"
          ),
          #"SYSTEM_SYSRULES_columnLayout"()
        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {

              #"SYSTEM_SYSRULES_pieChartField"(
                series: {
                  #"SYSTEM_SYSRULES_chartSeries"(
                    label: "Confirmed",
                    data: local!completedAsksCount
                  ),
                  #"SYSTEM_SYSRULES_chartSeries"(
                    label: "In Process",
                    data: local!inProgressAsks
                  ),
                  if(
                    local!totalRotationalPlanned - local!asksCount > 0,
                    #"SYSTEM_SYSRULES_chartSeries"(
                      label: "Open",
                      data: local!totalRotationalPlanned - local!asksCount
                    ),
                    {}
                  )
                },
                style: "PIE",
                colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(
                  colors: {
                    #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992",
                    #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342",
                    #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348"
                  }
                ),
                showDataLabels: true,
                seriesLabelStyle: "LEGEND",
                height: "MEDIUM"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(),

        }
      ),
      #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12877013"(
        fiscalYear: ri!fiscalYear,
        region: local!selectedRegion,
        selectedBU: local!selectedBU,
        bus: if(
          contains({ 2022 }, ri!fiscalYear),
          local!oldBus,
          if(
            contains({ 2023 }, ri!fiscalYear),
            {local!oldBus,local!newBus},
            local!newBus
          )         
        ),
        rotationalAskPlan: local!rotationalAskPlan
      )
    }
  )
)
